export const checkInUserToEvent = async (eventId: string, userId: string) => {
  try {
    // Check if the user is already checked in
    const { data: existingCheckIn, error: checkError } = await supabase
      .from('event_attendees_new')
      .select('*')
      .eq('event_id', eventId)
      .eq('user_id', userId)
      .maybeSingle();
      
    if (checkError) throw checkError;
    
    if (existingCheckIn) {
      // User is already checked in
      return true;
    }
    
    // Check in the user
    const { error: insertError } = await supabase
      .from('event_attendees_new')
      .insert({ event_id: eventId, user_id: userId });
      
    if (insertError) throw insertError;
    
    // Also increment the user's events_attended count using a manual update
    // Instead of using RPC function which doesn't exist in the types
    const { data: profile, error: profileError } = await supabase
      .from('profiles')
      .select('events_attended')
      .eq('id', userId)
      .single();
      
    if (profileError) throw profileError;
    
    const currentCount = profile.events_attended || 0;
    
    const { error: updateError } = await supabase
      .from('profiles')
      .update({ events_attended: currentCount + 1 })
      .eq('id', userId);
      
    if (updateError) throw updateError;
    
    return true;
  } catch (error) {
    console.error("Error checking in user to event:", error);
    return false;
  }
};

