export const createEventReminderNotifications = async () => {
  try {
    // Get all upcoming events within the next 24 hours
    const now = new Date();
    const oneDayLater = new Date(now.getTime() + 24 * 60 * 60 * 1000);
    
    const { data: upcomingEvents, error: eventsError } = await supabase
      .from('events')
      .select('id, title, event_date')
      .gte('event_date', now.toISOString())
      .lte('event_date', oneDayLater.toISOString())
      .eq('is_active', true);
      
    if (eventsError) throw eventsError;
    
    if (!upcomingEvents || upcomingEvents.length === 0) {
      return { success: true, message: "No upcoming events found within the next 24 hours" };
    }
    
    // For each event, get interested users and create notifications
    let notificationsCreated = 0;
    
    for (const event of upcomingEvents) {
      const { data: interestedUsers, error: usersError } = await supabase
        .from('event_interested')
        .select('user_id')
        .eq('event_id', event.id);
        
      if (usersError) {
        console.error(`Error getting interested users for event ${event.id}:`, usersError);
        continue;
      }
      
      if (!interestedUsers || interestedUsers.length === 0) {
        continue;
      }
      
      // Create a notification for each interested user
      for (const user of interestedUsers) {
        const { error: notificationError } = await supabase
          .from('notifications')
          .insert({
            user_id: user.user_id,
            title: 'Event Reminder',
            message: `"${event.title}" is coming up soon!`,
            type: 'event_reminder',
            related_id: event.id
          });
          
        if (notificationError) {
          console.error(`Error creating notification for user ${user.user_id}:`, notificationError);
          continue;
        }
        
        notificationsCreated++;
      }
    }
    
    return { 
      success: true, 
      message: `Created ${notificationsCreated} event reminder notifications` 
    };
  } catch (error) {
    console.error("Error creating event reminder notifications:", error);
    return { 
      success: false, 
      message: "Failed to create event reminder notifications" 
    };
  }
};
